class Cell {
  std::optional<Index> value_;
  mutable std::mutex mu_;
 public:
  const Index& get() {
    std::lock_guard<std::mutex> lk(mu_);
    if (!value_) value_ = Index::load(cfg_path());
    return *value_;
  }
  void reset() { std::lock_guard<std::mutex> lk(mu_); value_.reset(); }
};
